using System.Globalization;
using System.Net.Mail;

namespace Nethris.Kata;

public enum EmploymentStatus
{
    Active,
    OnLeave,
    Terminated
}

public enum SecurityRole
{
    Employee,
    Manager,
    Hr,
    Admin
}

public enum PtoStatus
{
    PendingManager,
    PendingHr,
    Approved,
    Rejected,
    Cancelled
}

public enum PtoDecision
{
    Approved,
    Rejected
}

public interface IVersioned
{
    Guid Id { get; set; }
    long Version { get; set; }
}

public sealed class HrisError(int status, string code, string message) : Exception(message)
{
    public int Status { get; } = status;
    public string Code { get; } = code;
    public static HrisError Invalid(string message) => new(422, "validation", message);
    public static HrisError Conflict(string message) => new(409, "conflict", message);
    public static HrisError Missing() => new(404, "not_found", "Record not found or not visible to your account.");
    public static HrisError Forbidden(string message = "Your current account cannot perform this action.") => new(403, "permission", message);
}

public sealed record Actor(Guid UserId, Guid EmployeeId, string Email, string Name, SecurityRole Role, long Version);

public sealed record PtoInput(DateOnly StartDate, DateOnly EndDate, decimal Hours, string Reason);
public sealed record DecisionInput(PtoDecision Decision, string? Comment);

public static class HrisRules
{
    public const int MaximumEmployees = 2000;
    public const int MaximumManagerDepth = 32;
    public static string Text(string? value, string field, int maximum = 120)
    {
        var normalized = value?.Trim();
        if (string.IsNullOrWhiteSpace(normalized) || normalized.Length > maximum || normalized.Any(char.IsControl))
            throw HrisError.Invalid($"{field} must contain 1–{maximum} characters without control characters.");
        return normalized;
    }
    public static string? OptionalText(string? value, string field, int maximum = 250) =>
        string.IsNullOrWhiteSpace(value) ? null : Text(value, field, maximum);
    public static string Email(string? value)
    {
        var email = Text(value, "Email", 254).ToLowerInvariant();
        if (!MailAddress.TryCreate(email, out var address) || address.Address != email || !email.Contains('.'))
            throw HrisError.Invalid("Enter a valid email address.");
        return email;
    }
    public static string Password(string? value)
    {
        if (value is null || value.Length < 12 || value.Length > 128)
            throw HrisError.Invalid("Use a password containing 12–128 characters.");
        return value;
    }
    public static int QuarterUnits(decimal hours, bool allowZero, decimal maximum)
    {
        if (hours < (allowZero ? 0m : .25m) || hours > maximum || decimal.Truncate(hours * 4m) != hours * 4m)
            throw HrisError.Invalid($"Hours must be in quarter-hour increments between {(allowZero ? "0" : "0.25")} and {maximum.ToString(CultureInfo.InvariantCulture)}.");
        return checked((int)(hours * 4m));
    }
    public static long Cents(decimal amount)
    {
        if (amount < 0 || amount > 100_000_000m || decimal.Round(amount, 2) != amount)
            throw HrisError.Invalid("Salary amounts must be 0–100,000,000 with at most two decimal places.");
        return checked((long)(amount * 100m));
    }
    public static T EnumValue<T>(T value) where T : struct, Enum =>
        Enum.IsDefined(value) ? value : throw HrisError.Invalid("Unknown enum value.");
    public static void Version(IVersioned value, long expected)
    {
        if (value.Version != expected) throw HrisError.Conflict("This record changed. Reload and review your draft before saving.");
    }
    public static void PtoDates(DateOnly start, DateOnly end, decimal hours, DateOnly today)
    {
        QuarterUnits(hours, false, 240);
        if (start < today || start > today.AddYears(1) || end < start || end.DayNumber - start.DayNumber > 30)
            throw HrisError.Invalid("Choose a future/current start within one year and an inclusive span of at most 31 calendar dates.");
        if (hours > (end.DayNumber - start.DayNumber + 1) * 8m)
            throw HrisError.Invalid("This workshop permits at most eight PTO hours per calendar date. Weekends are not excluded automatically.");
    }
    public static void ManagerChain(IReadOnlyDictionary<Guid, Guid?> managers, Guid employeeId, Guid? proposedManager)
    {
        var visited = new HashSet<Guid> { employeeId };
        var current = proposedManager;
        while (current is not null)
        {
            if (!visited.Add(current.Value)) throw HrisError.Conflict("A manager relationship cannot form a cycle.");
            if (visited.Count > MaximumManagerDepth + 1) throw HrisError.Conflict("Manager chains are limited to 32 levels in this workshop.");
            if (!managers.TryGetValue(current.Value, out current)) throw HrisError.Invalid("Manager does not exist.");
        }
    }
}

public sealed class Employee
{
    public Guid Id { get; set; }
    public EmploymentStatus Status { get; set; } = EmploymentStatus.Active;
    public decimal PtoBalanceHours { get; set; }
    public Guid? ManagerId { get; set; }
}

public sealed class PtoRequest : IVersioned
{
    public long Version { get; set; } = 1;
    public Guid Id { get; set; }
    public Guid EmployeeId { get; set; }
    public Employee? Employee { get; set; }
    public DateOnly StartDate { get; set; }
    public DateOnly EndDate { get; set; }
    public decimal Hours { get; set; }
    public Guid? AssignedManagerId { get; set; }
    public PtoStatus Status { get; set; } = PtoStatus.PendingManager;
    public List<PtoApproval> Approvals { get; set; } = [];
}

public sealed class PtoApproval
{
    public Guid Id { get; set; }
    public Guid PtoRequestId { get; set; }
    public Guid ApproverEmployeeId { get; set; }
    public required string Stage { get; set; }
    public PtoDecision Decision { get; set; }
    public string? Comment { get; set; }
}

public static class HrisPto
{
    public static bool Pending(PtoStatus status) => status is PtoStatus.PendingManager or PtoStatus.PendingHr;

    /// <summary>Save's active-request checks for request <paramref name="p"/> (new or being edited) by <paramref name="actor"/>.</summary>
    public static void CheckCapacity(IEnumerable<PtoRequest> requests, Actor actor, Employee employee, PtoRequest p, PtoInput input)
    {
        var open = requests.Where(other => other.Id != p.Id && other.EmployeeId == actor.EmployeeId &&
            (other.Status == PtoStatus.PendingManager || other.Status == PtoStatus.PendingHr || other.Status == PtoStatus.Approved)).ToList();
        if (open.Any(other => other.StartDate <= input.EndDate && other.EndDate >= input.StartDate)) throw HrisError.Conflict("These dates overlap an active PTO request.");
        if (open.Where(other => Pending(other.Status)).Sum(other => other.Hours) + input.Hours > employee.PtoBalanceHours)
            throw HrisError.Conflict("Insufficient balance after reserving other pending requests.");
    }

    /// <summary>Decide without persistence: records the approval on the request and returns it.</summary>
    public static PtoRequest Decide(Actor actor, PtoRequest p, long version, DecisionInput input)
    {
        HrisRules.EnumValue(input.Decision);
        if (actor.EmployeeId == p.EmployeeId || actor.Role < SecurityRole.Manager) throw HrisError.Forbidden("You cannot approve your own request.");
        HrisRules.Version(p, version);
        if (!Pending(p.Status)) throw HrisError.Conflict("This PTO request is already closed.");
        var stage = p.Status == PtoStatus.PendingManager ? "Manager" : "Hr";
        if (stage == "Manager" && (p.AssignedManagerId != actor.EmployeeId || p.Employee!.ManagerId != actor.EmployeeId))
            throw HrisError.Forbidden("The assigned current direct manager must make the first decision. The requester can cancel and resubmit after a manager change.");
        if (stage == "Hr" && (actor.Role < SecurityRole.Hr || p.Approvals.Any(a => a.ApproverEmployeeId == actor.EmployeeId)))
            throw HrisError.Forbidden("A different HR/Admin reviewer must make the final decision.");
        if (p.Employee!.Status == EmploymentStatus.Terminated) throw HrisError.Conflict("Terminated employees cannot receive PTO decisions.");
        if (input.Decision == PtoDecision.Rejected) p.Status = PtoStatus.Rejected;
        else if (stage == "Manager") p.Status = PtoStatus.PendingHr;
        else
        {
            if (p.Employee.PtoBalanceHours < p.Hours) throw HrisError.Conflict("PTO balance is insufficient.");
            p.Employee.PtoBalanceHours -= p.Hours; p.Status = PtoStatus.Approved;
        }
        p.Approvals.Add(new PtoApproval { Id = Guid.NewGuid(), PtoRequestId = p.Id, ApproverEmployeeId = actor.EmployeeId, Stage = stage,
            Decision = input.Decision, Comment = HrisRules.OptionalText(input.Comment, "Comment", 500) });
        return p;
    }
}

