using Nethris.Kata;

// Fixtures follow astraupskill/advanced/extended-course/09-reservations-and-balance-accounting.md:15 (balance 40, an 8h
// request approved -> stored balance 32), sized so that double counting the approved 8h CHANGES acceptance (ibid. :9).
public sealed class PtoReservationTests
{
    private static readonly Guid EmployeeId = Guid.NewGuid();
    private static readonly Actor Requester = new(Guid.NewGuid(), EmployeeId, "e@example.test", "Erin", SecurityRole.Employee, 1);

    private static PtoRequest Existing(PtoStatus status, DateOnly start, decimal hours) =>
        new() { Id = Guid.NewGuid(), EmployeeId = EmployeeId, StartDate = start, EndDate = start, Hours = hours, Status = status };

    private static PtoInput Input(DateOnly start, int days, decimal hours) => new(start, start.AddDays(days - 1), hours, "Trip");

    [Fact(DisplayName = "approved PTO is already deducted: 30h against a stored balance of 32 is accepted")]
    public void ApprovedHours_AreNotReservedAgain()
    {
        var employee = new Employee { Id = EmployeeId, PtoBalanceHours = 32 };
        var approved = Existing(PtoStatus.Approved, new DateOnly(2026, 10, 1), 8);
        var draft = new PtoRequest { Id = Guid.NewGuid(), EmployeeId = EmployeeId };

        HrisPto.CheckCapacity([approved], Requester, employee, draft, Input(new DateOnly(2026, 11, 2), 4, 30));
    }

    [Fact(DisplayName = "PENDING hours are reserved: pending 8h + new 30h against 32 is refused (409)")]
    public void PendingHours_AreReserved()
    {
        var employee = new Employee { Id = EmployeeId, PtoBalanceHours = 32 };
        var pending = Existing(PtoStatus.PendingHr, new DateOnly(2026, 10, 1), 8);
        var draft = new PtoRequest { Id = Guid.NewGuid(), EmployeeId = EmployeeId };

        var error = Assert.Throws<HrisError>(() => HrisPto.CheckCapacity([pending], Requester, employee, draft, Input(new DateOnly(2026, 11, 2), 4, 30)));
        Assert.Equal(409, error.Status);
    }

    [Fact(DisplayName = "the request being edited does not reserve against itself")]
    public void EditedRequest_IsExcluded()
    {
        var employee = new Employee { Id = EmployeeId, PtoBalanceHours = 32 };
        var editing = Existing(PtoStatus.PendingManager, new DateOnly(2026, 11, 2), 8);

        HrisPto.CheckCapacity([editing], Requester, employee, editing, Input(new DateOnly(2026, 11, 2), 4, 30));
    }

    [Fact(DisplayName = "an approved request still blocks overlapping dates (inclusive endpoints)")]
    public void ApprovedRequest_StillBlocksOverlap()
    {
        var employee = new Employee { Id = EmployeeId, PtoBalanceHours = 80 };
        var approved = Existing(PtoStatus.Approved, new DateOnly(2026, 11, 2), 8);
        var draft = new PtoRequest { Id = Guid.NewGuid(), EmployeeId = EmployeeId };

        var error = Assert.Throws<HrisError>(() => HrisPto.CheckCapacity([approved], Requester, employee, draft, Input(new DateOnly(2026, 10, 30), 4, 8)));
        Assert.Contains("overlap", error.Message);
    }
}

