using Nethris.Kata;

// astraupskill/advanced/extended-course/10-approval-workflows-and-authority.md:7-9: the HR stage needs a DIFFERENT
// final reviewer; an HR-role person who decided the manager stage cannot also make the final decision.
public sealed class PtoDecisionTests
{
    private sealed record World(Employee Requester, Actor ManagerWhoIsHr, Actor OtherHr, PtoRequest Request);

    private static World Build()
    {
        var managerId = Guid.NewGuid();
        var requester = new Employee { Id = Guid.NewGuid(), ManagerId = managerId, PtoBalanceHours = 40 };
        var request = new PtoRequest
        {
            Id = Guid.NewGuid(), EmployeeId = requester.Id, Employee = requester, StartDate = new DateOnly(2026, 11, 2),
            EndDate = new DateOnly(2026, 11, 2), Hours = 8, AssignedManagerId = managerId, Status = PtoStatus.PendingManager,
        };
        return new World(
            requester,
            new Actor(Guid.NewGuid(), managerId, "m@example.test", "Morgan", SecurityRole.Hr, 1),
            new Actor(Guid.NewGuid(), Guid.NewGuid(), "h@example.test", "Harper", SecurityRole.Hr, 1),
            request);
    }

    private static DecisionInput Approve => new(PtoDecision.Approved, null);

    [Fact(DisplayName = "the HR-role manager who approved the manager stage cannot also make the final HR decision (403)")]
    public void ManagerStageApprover_CannotFinalize()
    {
        var w = Build();
        HrisPto.Decide(w.ManagerWhoIsHr, w.Request, 1, Approve);
        Assert.Equal(PtoStatus.PendingHr, w.Request.Status);

        var error = Assert.Throws<HrisError>(() => HrisPto.Decide(w.ManagerWhoIsHr, w.Request, 1, Approve));

        Assert.Equal(403, error.Status);
        Assert.Equal(PtoStatus.PendingHr, w.Request.Status);
        Assert.Equal(40, w.Requester.PtoBalanceHours);
    }

    [Fact(DisplayName = "a different HR reviewer finalizes: approved, balance deducted, two stages recorded")]
    public void DifferentHrReviewer_Finalizes()
    {
        var w = Build();
        HrisPto.Decide(w.ManagerWhoIsHr, w.Request, 1, Approve);

        HrisPto.Decide(w.OtherHr, w.Request, 1, Approve);

        Assert.Equal(PtoStatus.Approved, w.Request.Status);
        Assert.Equal(32, w.Requester.PtoBalanceHours);
        Assert.Equal(new[] { "Manager", "Hr" }, w.Request.Approvals.Select(a => a.Stage));
    }

    [Fact(DisplayName = "nobody approves their own request")]
    public void Requester_CannotDecideOwnRequest()
    {
        var w = Build();
        var self = new Actor(Guid.NewGuid(), w.Requester.Id, "e@example.test", "Erin", SecurityRole.Admin, 1);

        Assert.Equal(403, Assert.Throws<HrisError>(() => HrisPto.Decide(self, w.Request, 1, Approve)).Status);
    }

    [Fact(DisplayName = "only the assigned current manager may make the first decision")]
    public void OtherHr_CannotTakeManagerStage()
    {
        var w = Build();

        Assert.Equal(403, Assert.Throws<HrisError>(() => HrisPto.Decide(w.OtherHr, w.Request, 1, Approve)).Status);
    }
}
